-- Frozen legacy alert query, with synthetic model policy and a bound clock.
SELECT rt.model, MIN(EXTRACT(EPOCH FROM (b.expires_at - $1::timestamptz)) / 60)::int AS min_minutes_remaining FROM batches b JOIN request_templates_all rt ON rt.file_id = b.file_id WHERE b.expires_at IS NOT NULL AND b.completed_at IS NULL AND b.failed_at IS NULL AND b.cancelled_at IS NULL AND b.deleted_at IS NULL AND b.created_at > $1::timestamptz - INTERVAL '48 hours' AND b.expires_at > $1::timestamptz AND b.expires_at - $1::timestamptz < GREATEST(INTERVAL '10 minutes', LEAST(INTERVAL '30 minutes', (b.expires_at - b.created_at) / 48)) AND EXISTS (SELECT 1 FROM public.deployed_models dm JOIN public.deployment_groups dg ON dg.deployment_id = dm.id JOIN public.groups g ON g.id = dg.group_id WHERE g.name = 'Everyone' AND dm.deleted = false AND (dm.model_name = rt.model OR dm.alias = rt.model)) GROUP BY rt.model
